// 產生檔：node tools/build_course_v2.js（來源 tools/content/course_v2/）。不要手改。
window.BUZZ_COURSE_V2_LESSONS = Object.assign(window.BUZZ_COURSE_V2_LESSONS || {}, {"function-intro":{"id":"function-intro","prerequisites":[],"next":["domain-range"],"related":["derivative-definition"],"objectives":["說得出函數的意思：每一個輸入恰好對到一個輸出。","會把數字或整個式子代進 $f$，例如算出 $f(-2)$ 與 $f(a + 1)$。","會用鉛直線測試判斷一張圖是不是函數的圖形。"],"concept":[{"heading":"① 一台機器","body":["函數是一條規則：放一個數 $x$ 進去，出來一個數 $f(x)$。$f(x) = x^2 + 1$ 這台機器，放 2 出來 5，放 $-3$ 出來 10。","$f(2)$ 讀作「$f$ 在 2 的值」，不是 $f$ 乘以 2。$x$ 只是佔位的名字，寫成 $f(t) = t^2 + 1$ 是同一個函數。"],"tex":["f(x)=x^2+1,\\qquad f(2)=2^2+1=5,\\qquad f(-3)=(-3)^2+1=10"]},{"heading":"② 規定只有一條：一個輸入，恰好一個輸出","body":["同一個 $x$ 不能出來兩個不同的值。反過來沒有限制：不同的 $x$ 可以出來同一個值，例如 $f(2) = f(-2) = 5$ 完全沒問題。","$y^2 = x$ 不是 $y$ 對 $x$ 的函數：$x = 4$ 時 $y$ 可以是 2 也可以是 $-2$。$\\sqrt{}$ 這個符號規定只取非負的那個根（$\\sqrt{4} = 2$），就是為了讓 $\\sqrt{x}$ 成為函數。"]},{"heading":"③ 代進去的是「整個括號裡的東西」","body":["$f(a + 1)$ 的意思是：把規則裡每一個 $x$ 都換成 $(a + 1)$。所以 $f(a + 1) = (a + 1)^2 + 1 = a^2 + 2a + 2$。","它不是 $f(a) + 1 = a^2 + 2$。這個動作之後天天用：〈導數定義〉裡的 $f(x + h)$ 就是這樣代出來的。"]},{"heading":"④ 圖形與鉛直線測試","body":["函數的圖形是所有點 $(x, f(x))$ 畫出來的樣子。因為一個 $x$ 只有一個輸出，任何一條鉛直線最多碰到圖形一次。","反過來，只要找到一條鉛直線碰到兩次，這張圖就不是函數的圖形。圓 $x^2 + y^2 = 1$ 就不是：鉛直線 $x = 0$ 同時碰到 $(0, 1)$ 與 $(0, -1)$。"]}],"workedExamples":[{"title":"代數字，也代式子","prompt":"$f(x) = x^2 - 3x$。求 $f(-2)$ 與 $f(a + 1)$。","steps":["$f(-2)$：每個 $x$ 換成 $(-2)$。$(-2)^2 - 3(-2) = 4 + 6 = 10$。負數要整個加括號，$(-2)^2$ 是 4，不是 $-4$。","$f(a + 1)$：每個 $x$ 換成 $(a + 1)$。$(a + 1)^2 - 3(a + 1)$。","展開：$a^2 + 2a + 1 - 3a - 3 = a^2 - a - 2$。"],"answer":"$f(-2) = 10$，$f(a + 1) = a^2 - a - 2$"},{"title":"整理 $f(2 + h) - f(2)$","prompt":"$f(x) = x^2$。化簡 $\\frac{f(2 + h) - f(2)}{h}$（$h \\ne 0$）。","steps":["$f(2 + h) = (2 + h)^2 = 4 + 4h + h^2$；$f(2) = 4$。","相減：$f(2 + h) - f(2) = 4h + h^2$。","除以 $h$（$h \\ne 0$ 才能除）：$\\frac{4h + h^2}{h} = 4 + h$。"],"answer":"$4 + h$","note":"這個式子叫差商，是〈導數定義〉的主角。現在只要會代、會化簡。"},{"title":"哪一個是函數","prompt":"以 $x$ 為輸入，$y = x^2$ 與 $y^2 = x$ 哪一個是函數？","steps":["$y = x^2$：給一個 $x$，平方只有一個結果。是函數。它的圖形是拋物線，每條鉛直線只碰一次。","$y^2 = x$：給 $x = 4$，$y^2 = 4$ 有 $y = 2$ 與 $y = -2$ 兩個解，一個輸入兩個輸出。不是函數。","它的圖形是開口向右的拋物線，鉛直線 $x = 4$ 碰到 $(4, 2)$ 與 $(4, -2)$ 兩點，鉛直線測試也不通過。"],"answer":"$y = x^2$ 是；$y^2 = x$ 不是"}],"pitfalls":["把 $f(a + 1)$ 寫成 $f(a) + 1$。","代負數沒加括號：$f(x) = x^2$ 時把 $f(-3)$ 算成 $-9$。","以為不同的輸入不能有相同的輸出。","把 $f(2)$ 讀成 $f$ 乘以 2。"],"sections":[{"title":"一台機器","beats":[{"show":["$f(x) = x^2 + 1$"],"note":"函數是一條規則：放一個數進去，出來一個數。","say":"把函數想成一台機器。這一台的規則是：放進去的數先平方，再加一。","au":"77c08198","ms":7824},{"show":["放 2 → $f(2) = 2^2 + 1 = 5$"],"say":"放二進去，二的平方是四，再加一，出來就是五。","au":"8ad82373","ms":5592},{"show":["放 $-3$ → $f(-3) = (-3)^2 + 1 = 10$"],"say":"放負三進去也一樣：負三的平方是九，加一，得到十。","au":"e3a36f6e","ms":5952},{"show":["$f(2)$ 讀作「$f$ 在 2 的值」"],"note":"不是 $f$ 乘以 2。","say":"這裡的括號不是乘法。f 後面括號裡的二，是放進機器的那個數，整個讀作 f 在二的值。","au":"f25cdd23","ms":9072}],"check":0},{"title":"一個輸入，一個輸出","beats":[{"show":["同一個 $x$ → 恰好一個輸出"],"note":"函數只有這一條規定。","say":"函數的規定只有一條：同一個 x 放進去，每次出來的都是同一個值。","au":"75f1a668","ms":6744},{"show":["$f(2) = f(-2) = 5$ 沒問題"],"note":"反過來沒有限制：不同的輸入可以出來同一個值。","say":"反過來就沒有限制了。二和負二放進去都出來五，兩個輸入撞到同一個輸出，完全沒問題。","au":"dbe780e7","ms":9696},{"show":["$y^2 = x$：$x = 4$ 時 $y = 2$ 或 $-2$"],"note":"一個輸入兩個輸出，不是函數。","say":"y 平方等於 x 就不行。x 是四的時候，y 可以是二，也可以是負二，一個輸入出來兩個答案。","au":"a3c4b34b","ms":9600},{"show":["$\\sqrt{4} = 2$"],"note":"$\\sqrt{}$ 只取非負的根，$\\sqrt{x}$ 才是函數。","say":"所以根號規定只取不是負的那個根，根號四就是二。這樣根號 x 才算得上是函數。","au":"0e442674","ms":8832}],"check":3},{"title":"代進去的是整個括號","beats":[{"show":["$f(a + 1)$：每個 $x$ 換成 $(a + 1)$"],"say":"f 在 a 加一的值，意思是把規則裡每一個 x，都換成一整包的 a 加一。","au":"3fcdd40a","ms":6528},{"show":["$f(a + 1) = (a + 1)^2 + 1 = a^2 + 2a + 2$"],"note":"$f(x) = x^2 + 1$ 的例子。","say":"用 x 平方加一這條規則：a 加一整個平方，再加一，展開是 a 平方加二 a 加二。","au":"eefe1aea","ms":7824},{"show":["$f(a) + 1 = a^2 + 2$"],"note":"這是另一個東西，不要混在一起。","say":"注意，f 在 a 的值再加一，是 a 平方加二。它跟上一行是兩個不一樣的東西。","au":"aebd500f","ms":8160},{"show":["$(-2)^2 - 3(-2) = 4 + 6 = 10$"],"note":"$f(x) = x^2 - 3x$ 代 $-2$：負數要整個加括號。","say":"代負數一定要整個加括號。x 平方減三 x 代負二，是四加六，等於十。","au":"ba7c423d","ms":8088}],"check":1},{"title":"鉛直線測試","beats":[{"show":["圖形 = 所有點 $(x, f(x))$"],"say":"函數的圖形，就是把每一個 x 和它的輸出配成一個點，全部畫出來。","au":"8536dde0","ms":6600},{"show":["鉛直線最多碰圖形一次"],"note":"因為一個 $x$ 只有一個輸出。","say":"一個 x 只有一個輸出，所以任何一條鉛直線，最多只會碰到圖形一次。","au":"5db089bb","ms":6816},{"show":["圓 $x^2 + y^2 = 1$：$x = 0$ 碰到兩點"],"note":"$(0, 1)$ 與 $(0, -1)$：不是函數的圖形。","say":"圓就不行。鉛直線 x 等於零，同時碰到上面和下面兩個點，所以圓不是函數的圖形。","au":"f2f62caa","ms":9312}],"check":2},{"title":"整理差商","beats":[{"show":["$f(x) = x^2$","化簡 $\\frac{f(2 + h) - f(2)}{h}$"],"note":"這個式子叫差商，是〈導數定義〉的主角。","say":"來整理一個式子：f 在二加 h 的值，減掉 f 在二的值，再除以 h。學導數的時候，它就是主角。","au":"875db0a9","ms":10344},{"show":["$f(2 + h) = 4 + 4h + h^2$，$f(2) = 4$"],"say":"二加 h 整個平方，展開是四加四 h 加 h 平方；f 在二的值是四。","au":"0bfde9c7","ms":6552},{"show":["相減：$4h + h^2$"],"say":"兩個相減，四剛好消掉，剩下四 h 加 h 平方。除以 h 之後會是什麼？先猜猜看。","au":"57282d2b","ms":9744}],"predict":{"ask":"除以 $h$（$h \\ne 0$）之後是？","options":[{"label":"$4 + h$","correct":true},{"label":"$4$","why":"$\\frac{h^2}{h} = h$ 還在，不會自己消失。"},{"label":"$4h$","why":"分子兩項都要除以 $h$：$\\frac{4h}{h} = 4$、$\\frac{h^2}{h} = h$。"}]}}],"checks":[{"ask":"$f(x) = 3x - 1$，$f(2)$ 是多少？","options":[{"label":"6","why":"$3 \\times 2 = 6$ 之後還要減 1。"},{"label":"5","correct":true},{"label":"$3x - 1$","why":"$f(2)$ 是把 2 代進去之後得到的一個數，不再是含 $x$ 的式子。"}]},{"ask":"$f(x) = x^2$，$f(a + 1)$ 是？","options":[{"label":"$a^2 + 1$","why":"那是 $f(a) + 1$。$f(a + 1)$ 要把整個 $a + 1$ 平方。"},{"label":"$2(a + 1)$","why":"平方是自己乘自己，不是乘 2。"},{"label":"$a^2 + 2a + 1$","correct":true}]},{"ask":"以 $x$ 為輸入，下面哪一個是函數？","options":[{"label":"$y = x^2$","correct":true},{"label":"$y^2 = x$","why":"$x = 4$ 時 $y$ 可以是 2 也可以是 $-2$，一個輸入兩個輸出。"},{"label":"$x^2 + y^2 = 1$","why":"這是圓，$x = 0$ 時 $y = 1$ 和 $y = -1$ 都滿足，鉛直線 $x = 0$ 碰到兩點。"}]},{"ask":"$f(2) = 5$ 而且 $f(-2) = 5$。這代表？","options":[{"label":"$f$ 不是函數","why":"規定的是「一個輸入只能有一個輸出」；兩個輸入共用一個輸出是允許的。"},{"label":"沒有問題，不同的輸入可以有相同的輸出","correct":true},{"label":"$f$ 一定是常數函數","why":"兩個點的值相同不代表全部相同，例如 $f(x) = x^2 + 1$ 就符合，但它不是常數。"}]}],"practice":[]},"domain-range":{"id":"domain-range","prerequisites":["function-intro"],"next":["piecewise-function"],"related":["exp-log","limit-factor"],"objectives":["找得出一個式子的定義域：分母、偶次根號、對數三個禁區，同時檢查。","會用區間寫答案：[ ]、( )、$\\cup$。","會找簡單函數的值域，而且知道要確認「每個值都拿得到」。"],"concept":[{"heading":"① 定義域：放得進去的 $x$","body":["題目只給式子、沒另外說的時候，定義域指「讓式子有意義的所有實數 $x$」。多項式什麼都能放，定義域是全體實數。"]},{"heading":"② 三個禁區","body":["分母不能是 0：$\\frac{1}{x - 3}$ 要 $x \\ne 3$。","偶次根號裡不能是負的：$\\sqrt{x + 3}$ 要 $x + 3 \\ge 0$。奇次根號沒有限制，$\\sqrt[3]{-8} = -2$。","對數裡要是正的：$\\ln(x - 1)$ 要 $x - 1 > 0$，等號不行（$\\ln$ 是什麼見〈指數與對數〉）。"]},{"heading":"③ 好幾個條件：同時成立","body":["$\\frac{\\sqrt{x}}{x - 4}$：根號要 $x \\ge 0$，分母要 $x \\ne 4$，兩個都要成立，定義域是 $[0, 4) \\cup (4, \\infty)$。","$\\frac{1}{\\sqrt{x - 2}}$：根號要 $x - 2 \\ge 0$，但它又在分母，不能是 0，合起來是 $x - 2 > 0$。","先化簡再找定義域會出錯：$\\frac{x^2 - 1}{x - 1}$ 可以約成 $x + 1$，但原式在 $x = 1$ 分母是 0，定義域仍然是 $x \\ne 1$。這件事在〈0/0：因式分解〉會變成主角。"]},{"heading":"④ 區間的寫法","body":["$[a, b]$ 包含兩端，$(a, b)$ 不包含，$[a, b)$ 包左不包右；$\\cup$ 是「或」，把兩段接起來。$\\infty$ 不是一個數，永遠配小括號：$[1, \\infty)$。"]},{"heading":"⑤ 值域：真的跑得出來的輸出","body":["$f(x) = x^2 + 1$：$x^2 \\ge 0$，所以 $f(x) \\ge 1$。但這只說了「不會低於 1」，還要說「每個 $\\ge 1$ 的值都拿得到」：給 $y \\ge 1$，取 $x = \\sqrt{y - 1}$ 就有 $f(x) = y$。兩個方向都對，值域才是 $[1, \\infty)$。","再一個：$\\frac{1}{x}$ 的值域是「除了 0 以外的所有實數」。任何 $y \\ne 0$ 都能用 $x = \\frac{1}{y}$ 拿到，但 $\\frac{1}{x} = 0$ 沒有解。從圖形看，值域就是圖形在 $y$ 方向蓋到的範圍。"]}],"workedExamples":[{"title":"根號加分母","prompt":"$f(x) = \\frac{\\sqrt{x + 3}}{x - 1}$ 的定義域","steps":["根號：$x + 3 \\ge 0$，$x \\ge -3$。","分母：$x - 1 \\ne 0$，$x \\ne 1$。","兩個同時成立：$x \\ge -3$ 而且 $x \\ne 1$。","寫成區間：$[-3, 1) \\cup (1, \\infty)$。$-3$ 用中括號，因為 $\\sqrt{0} = 0$ 可以，而且 $x = -3$ 時分母是 $-4$，沒問題。"],"answer":"$[-3, 1) \\cup (1, \\infty)$"},{"title":"對數裡是二次式","prompt":"$f(x) = \\ln(4 - x^2)$ 的定義域","problemId":"si-int-011","steps":["對數裡要是正的：$4 - x^2 > 0$。","移項：$x^2 < 4$。","$x^2 < 4$ 的意思是 $x$ 跟 0 的距離小於 2：$-2 < x < 2$。不是只有 $x < 2$（$x = -3$ 時 $x^2 = 9$，不行）。","端點不含：$x = \\pm2$ 時 $4 - x^2 = 0$，$\\ln 0$ 沒有定義。"],"answer":"$(-2, 2)$"},{"title":"配方找值域","prompt":"$f(x) = x^2 - 4x + 5$ 的值域","steps":["配方：$x^2 - 4x + 5 = (x^2 - 4x + 4) + 1 = (x - 2)^2 + 1$。","$(x - 2)^2 \\ge 0$，所以 $f(x) \\ge 1$；$x = 2$ 時剛好是 1。","每個 $y \\ge 1$ 都拿得到：解 $(x - 2)^2 + 1 = y$，得 $x = 2 + \\sqrt{y - 1}$。","值域是 $[1, \\infty)$。"],"answer":"$[1, \\infty)$"}],"pitfalls":["$\\frac{1}{\\sqrt{x - 2}}$ 寫成 $x \\ge 2$：$x = 2$ 時分母是 0。","對數裡寫成 $\\ge 0$：$\\ln 0$ 沒有定義。","$\\sqrt{x^2 - 1}$ 只寫 $x \\ge 1$，漏了 $x \\le -1$。","先約分再找定義域，把原本分母為 0 的點放了回去。","值域只說「不會低於多少」，沒確認每個值都拿得到。"],"sections":[{"title":"放得進去的 $x$","beats":[{"show":["定義域 = 讓式子有意義的 $x$"],"note":"多項式什麼都能放，定義域是全體實數。","say":"定義域就是能放進去的 x。題目沒特別說的時候，就是讓式子有意義的所有實數。","au":"40c31696","ms":8280},{"show":["禁區一：分母不能是 0"],"note":"$\\frac{1}{x - 3}$ 要 $x \\ne 3$。","say":"第一個禁區：分母不能是零。像一除以 x 減三，x 就不能等於三。","au":"afa0a5c0","ms":7440}],"check":0},{"title":"根號與對數","beats":[{"show":["禁區二：偶次根號裡 $\\ge 0$"],"note":"$\\sqrt{x + 3}$ 要 $x + 3 \\ge 0$。","say":"第二個禁區是偶次根號，裡面不能是負的。根號 x 加三，就要 x 加三大於等於零。","au":"017d01aa","ms":8976},{"show":["奇次根號沒有限制：$\\sqrt[3]{-8} = -2$"],"say":"奇次根號就沒有這個限制：負八開三次方根，答案是負二。","au":"0ce51ee3","ms":6096},{"show":["禁區三：對數裡 $> 0$"],"note":"$\\ln(x - 1)$ 要 $x - 1 > 0$，等號不行。","say":"第三個禁區是對數，裡面要大於零。自然對數 x 減一，x 減一要大於零，等於零也不行。","au":"f54a6324","ms":9600}],"check":1},{"title":"幾個條件同時成立","beats":[{"show":["$f(x) = \\frac{\\sqrt{x + 3}}{x - 1}$"],"say":"這個函數分子有根號，分母有 x 減一，兩個禁區要同時檢查。","au":"5c7682b1","ms":6360},{"show":["根號：$x \\ge -3$"],"say":"先看根號：x 加三大於等於零，也就是 x 大於等於負三。","au":"807117bd","ms":5856},{"show":["分母：$x \\ne 1$"],"say":"再看分母：x 減一不能是零，所以 x 不能等於一。","au":"874f961f","ms":5256},{"show":["$[-3, 1) \\cup (1, \\infty)$"],"note":"$-3$ 用中括號：$\\sqrt{0} = 0$，分母是 $-4$。","say":"合起來，是從負三一路往右，只挖掉一。負三放得進去，所以用中括號；一挖掉了，用小括號。","au":"63bc9182","ms":10632},{"show":["根號在分母：要 $> 0$"],"note":"$\\frac{1}{\\sqrt{x - 2}}$ 的根號不能是 0。","say":"如果根號在分母，像一除以根號 x 減二，根號就不能是零，條件要改成大於零。","au":"beec2cdc","ms":7920}],"check":2},{"title":"先化簡會出錯","beats":[{"show":["$\\frac{x^2 - 1}{x - 1}$ 約成 $x + 1$？"],"note":"約分是在 $x \\ne 1$ 的前提下做的。","say":"x 平方減一，除以 x 減一，看起來可以約成 x 加一。但約分是在 x 不等於一的前提下做的。","au":"da6cf706","ms":9480},{"show":["原式在 $x = 1$ 分母是 0"],"note":"定義域仍然是 $x \\ne 1$。","say":"原本的式子在 x 等於一的時候，分母是零，所以定義域還是要扣掉一。","au":"1932b3a0","ms":6864},{"show":["$[a, b]$ 包含兩端，$(a, b)$ 不包含"],"note":"$\\infty$ 不是一個數，永遠配小括號。","say":"順便記一下寫法：中括號包含端點，小括號不包含。無限大不是一個數，永遠配小括號。","au":"d6239530","ms":9552}],"check":3},{"title":"值域","beats":[{"show":["$x^2 + 1 \\ge 1$"],"note":"這只說了「不會低於 1」。","say":"x 平方加一，最小是一。不過這只說了它不會低於一，還沒說每個值都拿得到。","au":"56a87f42","ms":8328},{"show":["給 $y \\ge 1$，取 $x = \\sqrt{y - 1}$"],"note":"每個值都拿得到，值域才是 $[1, \\infty)$。","say":"反過來，任給一個大於等於一的 y，取 x 等於根號 y 減一，就拿得到 y。兩邊都確認，值域才算數。","au":"88da4af2","ms":10320},{"show":["$x^2 - 4x + 5 = (x - 2)^2 + 1$"],"note":"配方，換一個式子。","say":"換一個式子，先配方，變成 x 減二的平方再加一。它的值域是多少？猜猜看。","au":"6d4e9f9e","ms":9216}],"predict":{"ask":"$f(x) = x^2 - 4x + 5$ 的值域是？","options":[{"label":"$[1, \\infty)$","correct":true},{"label":"$[5, \\infty)$","why":"5 是 $f(0)$；$x = 2$ 時 $f(2) = 1$，更低。"},{"label":"$(1, \\infty)$","why":"$x = 2$ 時剛好是 1，拿得到，要用中括號。"}]}}],"checks":[{"ask":"$g(x) = \\frac{1}{x + 2}$ 的定義域？","options":[{"label":"$x > -2$","why":"負的 $x$ 也放得進去，例如 $g(-5) = -\\frac{1}{3}$。只有讓分母變 0 的 $-2$ 不行。"},{"label":"除了 $-2$ 以外的所有實數","correct":true},{"label":"所有實數","why":"$x = -2$ 時分母是 0，$\\frac{1}{0}$ 沒有意義。"}]},{"ask":"$\\sqrt{x^2 - 1}$ 的定義域？","options":[{"label":"$(-\\infty, -1] \\cup [1, \\infty)$","correct":true},{"label":"$[1, \\infty)$","why":"漏了負的那一邊：$x = -2$ 時 $x^2 - 1 = 3 \\ge 0$，放得進去。"},{"label":"$(-1, 1)$","why":"這一段正好是 $x^2 - 1 < 0$ 的範圍，方向弄反了。"}]},{"ask":"$\\frac{1}{\\sqrt{x - 2}}$ 的定義域？","options":[{"label":"$[2, \\infty)$","why":"$x = 2$ 時分母是 $\\sqrt{0} = 0$，不能放。"},{"label":"$(-\\infty, 2)$","why":"根號裡要非負；$x < 2$ 時 $x - 2$ 是負的。"},{"label":"$(2, \\infty)$","correct":true}]},{"ask":"$f(x) = \\frac{x^2 - 1}{x - 1}$ 的定義域？","options":[{"label":"所有實數","why":"約成 $x + 1$ 是在 $x \\ne 1$ 的前提下做的；原式在 $x = 1$ 分母是 0。"},{"label":"$x \\ne 1$","correct":true},{"label":"$x \\ne 1$ 而且 $x \\ne -1$","why":"只有分母會出事。$x = -1$ 時分子是 0、分母是 $-2$，值是 0，沒問題。"}]}],"practice":[{"id":"si-int-003","core":true},{"id":"si-int-002","core":true},{"id":"si-int-001","core":true},{"id":"si-int-013","core":true},{"id":"si-int-015"},{"id":"si-int-012"},{"id":"si-int-014","challenge":true,"note":"挑戰：$\\ln(\\ln x)$ 要兩層都成立：$x > 0$，而且 $\\ln x > 0$。"}]},"piecewise-function":{"id":"piecewise-function","prerequisites":["function-intro","domain-range"],"next":["graph-features"],"related":["limit-one-sided"],"objectives":["看懂分段寫法：先判斷 $x$ 落在哪一段，再用那一段的式子。","知道分界點只屬於其中一段，圖上用實心點、空心點表示。","會把絕對值改寫成分段函數，解方程式時會檢查解落在哪一段。"],"concept":[{"heading":"① 一個函數，好幾條規則","body":["分段函數在不同的 $x$ 範圍用不同的式子。下面這個函數：$x < 1$ 時用 $x^2$，$x \\ge 1$ 時用 $2x + 1$。","算 $f(a)$ 的順序永遠一樣：先看 $a$ 落在哪一段，再代那一段的式子。$f(-2) = (-2)^2 = 4$，$f(3) = 2\\cdot3 + 1 = 7$。"],"tex":["f(x)=\\begin{cases} x^2, & x<1 \\\\ 2x+1, & x\\ge 1 \\end{cases}"]},{"heading":"② 分界點屬於哪一段","body":["$x = 1$ 只滿足 $x \\ge 1$，所以 $f(1) = 2\\cdot1 + 1 = 3$，跟 $x^2$ 那段無關。一個 $x$ 只能有一個輸出，所以分界點只能屬於其中一段。","圖上：實心點表示這一段包含端點，空心點表示不包含。上面的圖在 $(1, 3)$ 是實心點；$x^2$ 那段畫到 $(1, 1)$ 是空心點。"]},{"heading":"③ 兩段在分界點不一定接得起來","body":["$x$ 從左邊靠近 1，$x^2$ 靠近 1；從右邊靠近，$2x + 1$ 靠近 3。圖形在 $x = 1$ 斷開、往上跳了 2。","也有接得起來的：把右段換成 $2x - 1$，右邊靠近 1，兩段就接上了。怎麼精確描述「從左邊靠近」「從右邊靠近」，是〈左極限與右極限〉的內容。"]},{"heading":"④ 絕對值就是分段函數","body":["$|x| = x$（$x \\ge 0$），$|x| = -x$（$x < 0$）。$x$ 是負的時候，$-x$ 才是正的：$|-3| = -(-3) = 3$。","$|x - 3|$ 的分界點是讓裡面等於 0 的 $x = 3$：$x \\ge 3$ 時是 $x - 3$，$x < 3$ 時是 $3 - x$。"]}],"workedExamples":[{"title":"分界點代哪一段","prompt":"$f(x) = x^2$（$x < 1$）、$2x + 1$（$x \\ge 1$）。求 $f(-2)$、$f(1)$、$f(3)$。","steps":["$-2 < 1$，用第一段：$f(-2) = (-2)^2 = 4$。","1 不滿足 $x < 1$，滿足 $x \\ge 1$，用第二段：$f(1) = 2 + 1 = 3$。","$3 \\ge 1$，用第二段：$f(3) = 7$。"],"answer":"$f(-2) = 4$，$f(1) = 3$，$f(3) = 7$"},{"title":"把絕對值拆開","prompt":"把 $g(x) = |x - 3| + x$ 寫成分段函數","steps":["分界點：$x - 3 = 0$，$x = 3$。","$x \\ge 3$：$x - 3 \\ge 0$，$|x - 3| = x - 3$，$g(x) = (x - 3) + x = 2x - 3$。","$x < 3$：$x - 3 < 0$，$|x - 3| = -(x - 3) = 3 - x$，$g(x) = (3 - x) + x = 3$。","$g(x) = 3$（$x < 3$），$2x - 3$（$x \\ge 3$）。檢查分界點：兩段在 $x = 3$ 都是 3，接得起來。"],"answer":"$g(x) = 3$（$x < 3$）；$2x - 3$（$x \\ge 3$）"},{"title":"解方程式要檢查段落","prompt":"$f(x) = x^2$（$x < 1$）、$2x + 1$（$x \\ge 1$）。解 $f(x) = 4$。","steps":["第一段：$x^2 = 4$，$x = 2$ 或 $x = -2$。但這一段只管 $x < 1$，$x = 2$ 不在範圍內，丟掉；$x = -2$ 留下。","第二段：$2x + 1 = 4$，$x = \\frac{3}{2}$。$\\frac{3}{2} \\ge 1$，在範圍內，留下。","檢查：$f(-2) = 4$，$f\\left(\\frac{3}{2}\\right) = 2\\cdot\\left(\\frac{3}{2}\\right) + 1 = 4$。"],"answer":"$x = -2$ 或 $x = \\frac{3}{2}$"}],"pitfalls":["分界點代錯段：$f(1)$ 用了 $x < 1$ 那段。","解出來的 $x$ 沒檢查是否落在那一段的範圍。","$|x|$ 在 $x < 0$ 的那段寫成 $x$，應該是 $-x$。","以為分段函數在分界點一定接得起來。"],"checks":[{"ask":"$f(x) = x + 1$（$x < 0$）、$x^2$（$x \\ge 0$）。$f(0)$ 是？","options":[{"label":"1","why":"這是用了 $x < 0$ 那段；但 0 不滿足 $x < 0$。"},{"label":"0","correct":true},{"label":"沒有定義","why":"0 滿足 $x \\ge 0$，屬於第二段，$f(0) = 0^2 = 0$。"}]},{"ask":"$x < 0$ 時，$|x|$ 等於？","options":[{"label":"$x$","why":"$x < 0$ 時 $x$ 是負的，絕對值要是非負的。"},{"label":"$x^2$","why":"$x^2$ 也非負，但值不一樣：$x = -3$ 時 $x^2 = 9$，$|x| = 3$。"},{"label":"$-x$","correct":true}]},{"ask":"$f(x) = x^2$（$x < 1$）、$2x + 1$（$x \\ge 1$）。$f(x) = 4$ 的解是？","options":[{"label":"$x = -2$ 或 $x = \\frac{3}{2}$","correct":true},{"label":"$x = 2$、$-2$ 或 $\\frac{3}{2}$","why":"$x = 2$ 不滿足 $x < 1$，不能用第一段的式子；代進正確的第二段，$f(2) = 5$。"},{"label":"只有 $x = \\frac{3}{2}$","why":"漏了第一段：$x = -2 < 1$，而且 $(-2)^2 = 4$。"}]},{"ask":"分段函數的圖上，某一段在端點畫空心點，表示？","options":[{"label":"函數在那裡的值是 0","why":"空心點跟 0 無關，它只說這一段不包含這個端點。"},{"label":"這一段不包含那個端點；那一點的值要看另一段","correct":true},{"label":"函數在那裡一定沒有定義","why":"常常是另一段在同一個 $x$ 有實心點，例如 ① 的函數在 $x = 1$ 有 $f(1) = 3$。"}]}],"practice":[{"id":"gx-021","core":true,"note":"看圖：$x = 2$ 是兩段的分界點，先判斷它屬於哪一段。"}]},"graph-features":{"id":"graph-features","prerequisites":["function-intro"],"next":["function-arithmetic"],"related":["increasing-decreasing","intermediate-value-theorem"],"objectives":["從式子找出截距，並用零點把數線切段、判斷每段的正負。","說得出遞增、有界、偶函數、奇函數的定義，並會用代數檢查。","知道「舉一個反例」就能否定奇偶性，但「代幾個點都對」不能證明。"],"concept":[{"heading":"① 截距","body":["$y$ 截距：圖形碰 $y$ 軸的地方，也就是 $f(0)$。$x$ 截距（零點）：圖形碰 $x$ 軸的地方，也就是 $f(x) = 0$ 的解。$f(x) = x^3 - 4x$ 的 $y$ 截距是 0，零點是 $x(x - 2)(x + 2) = 0$ 的 $-2$、0、2。"]},{"heading":"② 正負：零點把數線切段","body":["一個在區間上不間斷的函數，要從正變負得經過 0（這是〈中間值定理〉的內容）。所以零點把數線切成幾段，每一段裡正負不變，代一個點就知道整段。","$x^3 - 4x$：$f(-3) = -15$，$f(-1) = 3$，$f(1) = -3$，$f(3) = 15$，所以 $(-\\infty, -2)$ 負、$(-2, 0)$ 正、$(0, 2)$ 負、$(2, \\infty)$ 正。"]},{"heading":"③ 遞增、遞減","body":["$f$ 在區間 $I$ 上遞增：$I$ 裡任取 $x_1 < x_2$，都有 $f(x_1) < f(x_2)$。遞減是 $f(x_1) > f(x_2)$。遞增說的是「往右走越來越高」，不是「$f(x) > 0$」。","目前用代數檢查；〈增減區間〉會用導數，快很多。"]},{"heading":"④ 有界","body":["存在一個數 $M$，讓所有 $x$ 都有 $|f(x)| \\le M$，就叫有界。$\\frac{1}{1 + x^2}$ 有界（$0 <$ 值 $\\le 1$）；$x^2$ 沒有上界；$\\frac{1}{x}$ 在 0 附近要多大有多大，也沒有界。"]},{"heading":"⑤ 對稱：偶函數與奇函數","body":["偶函數：對定義域裡每個 $x$ 都有 $f(-x) = f(x)$，圖形對 $y$ 軸對稱，例如 $x^2$、$x^4 - x^2$。奇函數：$f(-x) = -f(x)$，圖形對原點對稱，例如 $x^3$、$x^3 - 4x$。","「每個 $x$」是重點：代幾個點都對不算證明，要把 $-x$ 代進式子整理；但只要找到一個 $x$ 不對，就足以說「不是」。大部分函數既不奇也不偶。"]}],"workedExamples":[{"title":"截距與正負","prompt":"$f(x) = x^3 - 4x$：找截距、判斷正負、判斷奇偶。","steps":["$y$ 截距：$f(0) = 0$。零點：$x^3 - 4x = x(x^2 - 4) = x(x - 2)(x + 2) = 0$，$x = -2$、0、2。","零點切出四段，每段代一個點：$f(-3) = -27 + 12 = -15$，$f(-1) = -1 + 4 = 3$，$f(1) = 1 - 4 = -3$，$f(3) = 27 - 12 = 15$。","所以 $x < -2$ 負，$-2 < x < 0$ 正，$0 < x < 2$ 負，$x > 2$ 正。","奇偶：$f(-x) = (-x)^3 - 4(-x) = -x^3 + 4x = -(x^3 - 4x) = -f(x)$，奇函數。"],"answer":"截距 $(0, 0)$、$(\\pm2, 0)$；正負依序為 負、正、負、正；奇函數"},{"title":"證明是偶函數，或舉反例","prompt":"$g(x) = \\frac{x^2}{1 + x^4}$ 與 $h(x) = x + 1$ 是奇函數、偶函數，還是都不是？","steps":["$g(-x) = \\frac{(-x)^2}{1 + (-x)^4} = \\frac{x^2}{1 + x^4} = g(x)$，對每個 $x$ 都成立，偶函數。","$h(-1) = 0$、$h(1) = 2$。$h(-1) \\ne h(1)$，不是偶；$h(-1) \\ne -h(1) = -2$，不是奇。","$h$ 的判斷只用了一個 $x = 1$ 當反例，這就夠了。"],"answer":"$g$ 是偶函數；$h$ 既不奇也不偶"},{"title":"有界與遞減","prompt":"$f(x) = \\frac{1}{1 + x^2}$：它有界嗎？在 $[0, \\infty)$ 上遞增還是遞減？","steps":["$1 + x^2 \\ge 1$，所以 $0 < \\frac{1}{1 + x^2} \\le 1$，有界；$x = 0$ 時等於 1。","取 $0 \\le x_1 < x_2$：$x_1^2 < x_2^2$，所以 $1 + x_1^2 < 1 + x_2^2$。","分母大的分數比較小：$f(x_1) > f(x_2)$，在 $[0, \\infty)$ 上遞減。","$f$ 是偶函數，圖形對 $y$ 軸對稱，所以在 $(-\\infty, 0]$ 上遞增。"],"answer":"有界（$0 < f(x) \\le 1$）；在 $[0, \\infty)$ 遞減"}],"pitfalls":["奇偶只代一兩個點就宣稱是奇或偶。","以為不是偶函數就一定是奇函數。","正負只代一個點就判斷整條數線。","把「遞增」理解成「$f(x) > 0$」。"],"checks":[{"ask":"$f(x) = x^4 - x^2$ 是？","options":[{"label":"奇函數","why":"$f(-x) = x^4 - x^2 = f(x)$，等於 $f(x)$ 而不是 $-f(x)$。"},{"label":"偶函數","correct":true},{"label":"既不奇也不偶","why":"只有偶次方，$(-x)^4 = x^4$、$(-x)^2 = x^2$，$f(-x) = f(x)$ 對每個 $x$ 成立。"}]},{"ask":"$f(x) = x^3 - 4x$ 在 $(0, 2)$ 上是？","options":[{"label":"負的","correct":true},{"label":"正的","why":"只看 $x^3$ 會以為是正的，但這一段 $4x$ 比 $x^3$ 大，例如 $f(1) = -3$。"},{"label":"無法判斷","why":"零點只有 $-2$、0、2，$(0, 2)$ 裡沒有零點，代一點就知道整段。"}]},{"ask":"下面哪一個函數在它的定義域上有界？","options":[{"label":"$x^2$","why":"$x$ 越大 $x^2$ 越大，沒有上界。"},{"label":"$\\frac{1}{x}$","why":"$x$ 很靠近 0 時 $|\\frac{1}{x}|$ 要多大有多大。"},{"label":"$\\frac{1}{1 + x^2}$","correct":true}]},{"ask":"$h(x) = x + 1$ 是？","options":[{"label":"奇函數","why":"$h(-x) = -x + 1$，而 $-h(x) = -x - 1$，不相等。"},{"label":"偶函數","why":"$h(-1) = 0$、$h(1) = 2$，不相等。"},{"label":"既不奇也不偶","correct":true}]}],"practice":[{"id":"gx-025","core":true},{"id":"gx-024","core":true,"note":"折線的零點：在每一段直線上找 $y = 0$ 的位置。"}]},"function-arithmetic":{"id":"function-arithmetic","prerequisites":["function-intro","domain-range"],"next":["function-composition"],"related":["limit-factor","product-rule","quotient-rule"],"objectives":["會算 $(f + g)(x)$、$(f - g)(x)$、$(fg)(x)$、$\\left(\\frac{f}{g}\\right)(x)$，以及它們在某一點的值。","會找 $\\frac{f}{g}$ 的定義域：兩者都要有定義，而且分母 $g(x) \\ne 0$。","分得清 $fg$（相乘）與 $f(g(x))$（合成）。"],"concept":[{"heading":"① 逐點運算","body":["兩個函數相加，意思是在每一個 $x$ 把兩個輸出加起來：$(f + g)(x) = f(x) + g(x)$。減、乘、除同理。","$f(x) = \\sqrt{x}$、$g(x) = x - 2$：$(f + g)(4) = \\sqrt{4} + (4 - 2) = 4$，$(fg)(9) = 3 \\cdot 7 = 21$。"],"tex":["(f+g)(x)=f(x)+g(x),\\quad (fg)(x)=f(x)\\,g(x),\\quad \\left(\\frac{f}{g}\\right)(x)=\\frac{f(x)}{g(x)}"]},{"heading":"② 定義域：交集，除法再扣掉分母的零點","body":["$(f + g)(x)$ 要算得出來，$f(x)$ 和 $g(x)$ 都得有定義，所以定義域是兩者的交集。","$\\frac{f}{g}$ 還多一條：$g(x) \\ne 0$。上面的例子 $\\frac{f}{g} = \\frac{\\sqrt{x}}{x - 2}$，定義域是 $x \\ge 0$ 而且 $x \\ne 2$，也就是 $[0, 2) \\cup (2, \\infty)$。"]},{"heading":"③ 化簡不會改變定義域","body":["$f(x) = x^2 - 1$、$g(x) = x + 1$：$\\left(\\frac{f}{g}\\right)(x) = \\frac{(x - 1)(x + 1)}{x + 1} = x - 1$，但只在 $x \\ne -1$ 時成立。$\\frac{f}{g}$ 的圖形是直線 $y = x - 1$ 在 $(-1, -2)$ 挖了一個洞。","「化簡之後跟某條直線一樣，只差一個洞」——〈0/0：因式分解〉整課就在處理這個洞。"]},{"heading":"④ 相乘不是合成","body":["$fg$ 是兩個輸出相乘；$f(g(x))$ 是把 $g$ 的輸出餵給 $f$（下一課）。$f(x) = x^2$、$g(x) = x + 3$：$(fg)(x) = x^2(x + 3)$，$f(g(x)) = (x + 3)^2$，$x = 1$ 時一個是 4、一個是 16。","會把複雜的函數拆成「誰加誰、誰乘誰」，之後的〈乘法法則〉、〈除法法則〉就是在問：拆開之後怎麼微分。"]}],"workedExamples":[{"title":"求值與定義域","prompt":"$f(x) = \\sqrt{x}$、$g(x) = x - 2$。求 $(f + g)(4)$、$(fg)(9)$，以及 $\\frac{f}{g}$ 的定義域。","steps":["$(f + g)(4) = f(4) + g(4) = 2 + 2 = 4$。","$(fg)(9) = f(9) \\cdot g(9) = 3 \\cdot 7 = 21$。","$\\frac{f}{g}$：$f$ 要 $x \\ge 0$；$g$ 處處有定義；分母 $g(x) = x - 2 \\ne 0$，$x \\ne 2$。","合起來：$[0, 2) \\cup (2, \\infty)$。"],"answer":"4；21；$[0, 2) \\cup (2, \\infty)$"},{"title":"相減要整個括起來","prompt":"$f(x) = x^2 + 1$、$g(x) = 3x - 2$。求 $(f - g)(x)$ 與 $(fg)(x)$。","steps":["$(f - g)(x) = (x^2 + 1) - (3x - 2)$。減號要分配給 $g$ 的每一項：$x^2 + 1 - 3x + 2 = x^2 - 3x + 3$。","$(fg)(x) = (x^2 + 1)(3x - 2) = 3x^3 - 2x^2 + 3x - 2$。","檢查一點：$x = 1$ 時 $f(1) = 2$、$g(1) = 1$，$(f - g)(1) = 1$，代入 $x^2 - 3x + 3$ 也是 1。"],"answer":"$(f - g)(x) = x^2 - 3x + 3$；$(fg)(x) = 3x^3 - 2x^2 + 3x - 2$"},{"title":"化簡之後的洞","prompt":"$f(x) = x^2 - 9$、$g(x) = x - 3$。化簡 $\\frac{f}{g}$，並問 $\\left(\\frac{f}{g}\\right)(3)$ 是多少。","steps":["$\\left(\\frac{f}{g}\\right)(x) = \\frac{(x - 3)(x + 3)}{x - 3}$。","$x \\ne 3$ 時可以約掉 $x - 3$：$\\left(\\frac{f}{g}\\right)(x) = x + 3$。","但 $g(3) = 0$，3 不在 $\\frac{f}{g}$ 的定義域裡，$\\left(\\frac{f}{g}\\right)(3)$ 沒有定義。","$x + 3$ 在 3 的值是 6；這個 6 之後會變成「$x$ 靠近 3 時 $\\frac{f}{g}$ 靠近的值」。"],"answer":"$x \\ne 3$ 時 $\\left(\\frac{f}{g}\\right)(x) = x + 3$；$\\left(\\frac{f}{g}\\right)(3)$ 沒有定義"}],"pitfalls":["$\\frac{f}{g}$ 的定義域忘了扣掉 $g(x) = 0$ 的點。","化簡之後忘了原本的限制。","$(f - g)(x)$ 的減號沒有分配到 $g$ 的每一項。","把 $fg$ 跟 $f(g(x))$ 搞混。"],"checks":[{"ask":"$f(x) = x + 1$、$g(x) = x - 1$，$(fg)(x)$ 是？","options":[{"label":"$x^2 - 1$","correct":true},{"label":"$2x$","why":"那是 $f + g$。"},{"label":"$x$","why":"那是 $f(g(x)) = (x - 1) + 1$，合成不是相乘。"}]},{"ask":"$f(x) = x^2$、$g(x) = x - 3$，$(f - g)(x)$ 是？","options":[{"label":"$x^2 - x - 3$","why":"減號沒有分配：$-(x - 3) = -x + 3$。"},{"label":"$-x^2 + x - 3$","why":"那是 $g - f$，順序反了。"},{"label":"$x^2 - x + 3$","correct":true}]},{"ask":"$f(x) = \\sqrt{x}$、$g(x) = x - 4$，$\\frac{f}{g}$ 的定義域？","options":[{"label":"$[0, \\infty)$","why":"漏了 $g(4) = 0$，$x = 4$ 時分母是 0。"},{"label":"$[0, 4) \\cup (4, \\infty)$","correct":true},{"label":"$x \\ne 4$","why":"漏了 $\\sqrt{x}$ 要 $x \\ge 0$，負數放不進 $f$。"}]},{"ask":"$f(x) = x^2 - 9$、$g(x) = x - 3$。$\\left(\\frac{f}{g}\\right)(3)$ 是？","options":[{"label":"6","why":"6 是化簡式 $x + 3$ 在 3 的值；但 $g(3) = 0$，$\\left(\\frac{f}{g}\\right)(3)$ 本身沒有定義。"},{"label":"0","why":"$\\frac{0}{0}$ 不是 0，它根本不是一個數。"},{"label":"沒有定義","correct":true}]}],"practice":[]},"function-composition":{"id":"function-composition","prerequisites":["function-intro","function-arithmetic"],"next":["inverse-function"],"related":["chain-rule"],"objectives":["會算 $(f\\circ g)(x) = f(g(x))$：先算裡面的 $g$，再把結果放進 $f$。","看到一個式子能拆出「外面是誰、裡面是誰」。","會找合成函數的定義域，知道化簡後的式子可能比合成函數的定義域大。"],"concept":[{"heading":"① 把一個函數的輸出餵給另一個","body":["$(f\\circ g)(x) = f(g(x))$，讀作「$f$ 合成 $g$」。順序是從裡到外：先算 $g(x)$，再把它整個放進 $f$。","$f(x) = \\sqrt{x}$、$g(x) = x^2 + 1$：$f(g(x)) = \\sqrt{x^2 + 1}$，$g(f(x)) = (\\sqrt{x})^2 + 1$。兩者通常不一樣：$x = 2$ 時一個是 $\\sqrt{5}$，一個是 3。","自己合成自己也可以：$f(x) = 2x + 1$ 時，$f(f(x)) = 2(2x + 1) + 1 = 4x + 3$。"],"tex":["(f\\circ g)(x)=f\\big(g(x)\\big)"]},{"heading":"② 拆解：外面是誰，裡面是誰","body":["倒過來，看到一個複雜的式子，把「最後做的那一步」當外層。$(3x - 1)^5$：先算 $3x - 1$，最後才五次方，所以外層 $f(u) = u^5$，裡層 $g(x) = 3x - 1$。","$\\frac{1}{x^2 + 4}$：外層 $f(u) = \\frac{1}{u}$，裡層 $g(x) = x^2 + 4$。這個習慣是〈連鎖律 I：兩層〉的基本功：連鎖律就是「合成函數怎麼微分」。"]},{"heading":"③ 定義域：兩關都要過","body":["$x$ 要能放進 $g$，而且 $g(x)$ 要能放進 $f$。$f(x) = \\sqrt{x}$、$g(x) = x - 5$：$f(g(x)) = \\sqrt{x - 5}$ 要 $x - 5 \\ge 0$，所以是 $x \\ge 5$，不是 $x \\ge 0$。","化簡之後要記得原來的關卡。$g(f(x)) = (\\sqrt{x})^2 + 1$ 化簡成 $x + 1$，但 $x$ 必須先過 $\\sqrt{}$ 這關，定義域是 $x \\ge 0$，不是全體實數。"]}],"workedExamples":[{"title":"兩種順序","prompt":"$f(x) = \\sqrt{x}$、$g(x) = x^2 + 1$。寫出 $f(g(x))$ 與 $g(f(x))$，並各算 $x = 2$ 的值。","steps":["$f(g(x))$：先算 $g$，得 $x^2 + 1$；再開根號：$\\sqrt{x^2 + 1}$。$x = 2$ 時是 $\\sqrt{5}$。","$g(f(x))$：先算 $f$，得 $\\sqrt{x}$；再平方加 1：$(\\sqrt{x})^2 + 1 = x + 1$（$x \\ge 0$）。$x = 2$ 時是 3。","$\\sqrt{5} \\ne 3$，合成的順序不能交換。"],"answer":"$f(g(x)) = \\sqrt{x^2 + 1}$；$g(f(x)) = x + 1$（$x \\ge 0$）"},{"title":"拆出外層與裡層","prompt":"把 $h(x) = (3x - 1)^5$ 與 $k(x) = \\sqrt{1 - x^2}$ 寫成 $f(g(x))$。","steps":["$h$：最後一步是五次方。外層 $f(u) = u^5$，裡層 $g(x) = 3x - 1$。","$k$：最後一步是開根號。外層 $f(u) = \\sqrt{u}$，裡層 $g(x) = 1 - x^2$。","檢查：把 $g$ 代進 $f$ 的 $u$，應該拿回原式。"],"answer":"$h$：$f(u) = u^5$、$g(x) = 3x - 1$；$k$：$f(u) = \\sqrt{u}$、$g(x) = 1 - x^2$"},{"title":"化簡後定義域會變大","prompt":"$f(x) = \\sqrt{x}$、$g(x) = 1 - x^2$。求 $f(g(x))$ 與 $g(f(x))$ 的定義域。","steps":["$f(g(x)) = \\sqrt{1 - x^2}$：要 $1 - x^2 \\ge 0$，即 $-1 \\le x \\le 1$。定義域 $[-1, 1]$。","$g(f(x)) = 1 - (\\sqrt{x})^2$：$x$ 要先放進 $\\sqrt{}$，所以 $x \\ge 0$。","$x \\ge 0$ 時 $(\\sqrt{x})^2 = x$，$g(f(x)) = 1 - x$。式子 $1 - x$ 對所有實數都有意義，但 $g(f(x))$ 的定義域仍是 $[0, \\infty)$。"],"answer":"$f(g(x))$：$[-1, 1]$；$g(f(x))$：$[0, \\infty)$"}],"pitfalls":["把 $f(g(x))$ 當成 $f(x) \\cdot g(x)$。","順序弄反：$f(g(x))$ 先算 $g$，不是先算 $f$。","合成的定義域只看裡層，或只看化簡後的式子。","$(3x - 1)^5$ 的外層寫成「3 乘以 $x^5$」：括號是一整塊。"],"checks":[{"ask":"$f(x) = x^3$、$g(x) = 2x$，$f(g(x))$ 是？","options":[{"label":"$2x^3$","why":"那是 $g(f(x))$：先立方再乘 2。$f(g(x))$ 是先乘 2，再把整個 $2x$ 立方。"},{"label":"$8x^3$","correct":true},{"label":"$2x^4$","why":"那是 $f(x) \\cdot g(x)$，合成不是相乘。"}]},{"ask":"$h(x) = \\sqrt{x^2 + 1}$ 寫成 $f(g(x))$，哪一組對？","options":[{"label":"外層 $f(u) = \\sqrt{u}$，裡層 $g(x) = x^2 + 1$","correct":true},{"label":"外層 $f(u) = u^2 + 1$，裡層 $g(x) = \\sqrt{x}$","why":"合起來是 $(\\sqrt{x})^2 + 1 = x + 1$，不是 $h$。"},{"label":"外層 $f(u) = u^2$，裡層 $g(x) = \\sqrt{x + 1}$","why":"合起來是 $(\\sqrt{x + 1})^2 = x + 1$，也不是 $h$。"}]},{"ask":"$f(x) = x + 2$、$g(x) = x^2$。$f(g(3))$ 與 $g(f(3))$ 依序是？","options":[{"label":"25 和 11","why":"順序反了：$f(g(3))$ 先算 $g(3) = 9$，再加 2 得 11。"},{"label":"11 和 11","why":"$g(f(3)) = g(5) = 25$。合成通常不能交換。"},{"label":"11 和 25","correct":true}]},{"ask":"$f(x) = \\sqrt{x}$、$g(x) = x - 5$，$f(g(x))$ 的定義域？","options":[{"label":"$x \\ge 0$","why":"要非負的是放進 $\\sqrt{}$ 的東西 $g(x) = x - 5$，不是 $x$ 本身。"},{"label":"$x \\ge 5$","correct":true},{"label":"所有實數","why":"$x = 0$ 時 $g(0) = -5$，$\\sqrt{-5}$ 沒有定義。"}]}],"practice":[]},"inverse-function":{"id":"inverse-function","prerequisites":["function-composition","domain-range"],"next":["polynomial-rational"],"related":["inverse-trig","inverse-trig-derivative","exp-log"],"objectives":["說得出 $f^{-1}$ 在做什麼：$f(a) = b$ 的時候，$f^{-1}(b) = a$。","用水平線測試判斷有沒有反函數；沒有時知道要限制定義域。","會求反函數的式子，並知道定義域與值域互換、圖形對 $y = x$ 對稱。"],"concept":[{"heading":"① 反函數把 $f$ 做的事倒回去","body":["$f(x) = 2x + 3$ 把 1 送到 5。反函數 $f^{-1}$ 要把 5 送回 1。一般來說：$f(a) = b$ 若且唯若 $f^{-1}(b) = a$。","所以 $f^{-1}(f(x)) = x$，$f(f^{-1}(y)) = y$：先做再倒回去，等於什麼都沒做。"]},{"heading":"② 不是每個函數都倒得回去","body":["$f(x) = x^2$ 把 2 和 $-2$ 都送到 4。要倒回去時，4 該回到 2 還是 $-2$？沒辦法決定，所以 $x^2$ 在全體實數上沒有反函數。","能倒回去的條件是一對一：不同的 $x$ 一定給不同的輸出。圖形上就是水平線測試：每條水平線最多碰圖形一次。","不是一對一時，可以只取一部分：$x^2$ 限制在 $x \\ge 0$ 上就是一對一，它的反函數是 $\\sqrt{x}$。"]},{"heading":"③ 怎麼求","body":["寫 $y = f(x)$，把 $x$ 解成 $y$ 的式子，最後把字母名字換回 $x$。","定義域與值域互換：$f$ 的值域是 $f^{-1}$ 的定義域，$f$ 的定義域是 $f^{-1}$ 的值域。圖形上，$(a, b)$ 在 $f$ 上，$(b, a)$ 就在 $f^{-1}$ 上，兩張圖對直線 $y = x$ 對稱。"]},{"heading":"④ $f^{-1}$ 不是 $\\frac{1}{f}$","body":["$f^{-1}$ 的上標 $-1$ 表示反函數，不是倒數。$f(x) = x^3$ 時 $f^{-1}(8) = 2$，而 $\\frac{1}{f(8)} = \\frac{1}{512}$。","之後兩個最重要的反函數：$\\ln$ 是 $e^x$ 的反函數（〈指數與對數〉），$\\arcsin$ 是限制過的 $\\sin$ 的反函數（〈反三角函數〉）。"]}],"workedExamples":[{"title":"一次函數","prompt":"$f(x) = 2x + 3$，求 $f^{-1}(x)$。","steps":["寫 $y = 2x + 3$。","解 $x$：$2x = y - 3$，$x = \\frac{y - 3}{2}$。","換回 $x$ 當變數名：$f^{-1}(x) = \\frac{x - 3}{2}$。","檢查：$f(f^{-1}(x)) = 2 \\cdot \\frac{x - 3}{2} + 3 = x$。"],"answer":"$f^{-1}(x) = \\frac{x - 3}{2}$"},{"title":"先限制定義域","prompt":"$f(x) = x^2 - 1$（$x \\ge 0$），求 $f^{-1}(x)$ 與它的定義域、值域。","steps":["$x \\ge 0$ 時 $x^2$ 一對一，可以倒回去。$f$ 的值域：$x^2 \\ge 0$，所以 $f(x) \\ge -1$，值域 $[-1, \\infty)$。","寫 $y = x^2 - 1$，$x^2 = y + 1$，$x = \\pm\\sqrt{y + 1}$。","原本規定 $x \\ge 0$，所以取正號：$x = \\sqrt{y + 1}$。","$f^{-1}(x) = \\sqrt{x + 1}$，定義域 $[-1, \\infty)$（原本的值域），值域 $[0, \\infty)$（原本的定義域）。"],"answer":"$f^{-1}(x) = \\sqrt{x + 1}$，定義域 $[-1, \\infty)$，值域 $[0, \\infty)$"},{"title":"只求一個值，不必求式子","prompt":"$f(x) = x^3 + x$，求 $f^{-1}(2)$。","steps":["$f^{-1}(2)$ 問的是：哪個 $x$ 讓 $f(x) = 2$？也就是解 $x^3 + x = 2$。","試 $x = 1$：$1 + 1 = 2$，成立。","$f$ 是一對一的：$x$ 變大時 $x^3$ 與 $x$ 都變大，所以 $x^3 + x$ 也變大，不會有第二個解。","$f^{-1}(2) = 1$。"],"answer":"1","note":"$x^3 + x = y$ 解不出好看的 $x$，但求單一個值時不需要。〈反函數與反三角函數微分〉會接著問 $(f^{-1})'(2)$，第一步就是這個。"}],"pitfalls":["把 $f^{-1}(x)$ 當成 $\\frac{1}{f(x)}$。","沒有限制定義域就對 $x^2$ 求反函數。","解出 $\\pm$ 兩個根，沒有依原本的定義域挑號。","忘了定義域與值域要互換。"],"checks":[{"ask":"$f(x) = x^3$，$f^{-1}(8)$ 是？","options":[{"label":"$\\frac{1}{512}$","why":"那是 $\\frac{1}{f(8)}$。$f^{-1}$ 是反函數，不是倒數。"},{"label":"2","correct":true},{"label":"512","why":"那是 $f(8)$。$f^{-1}(8)$ 問的是哪個數的立方是 8。"}]},{"ask":"下面哪一個函數在全體實數上有反函數？","options":[{"label":"$x^3$","correct":true},{"label":"$x^2$","why":"$f(2) = f(-2) = 4$，水平線 $y = 4$ 碰到兩點，不是一對一。"},{"label":"$|x|$","why":"$|3| = |-3|$，同樣不是一對一。"}]},{"ask":"$f(x) = \\frac{x - 1}{3}$，$f^{-1}(x)$ 是？","options":[{"label":"$3x - 1$","why":"解 $y = \\frac{x - 1}{3}$ 得 $x = 3y + 1$：倒回去時「減 1」要變「加 1」。"},{"label":"$\\frac{3}{x - 1}$","why":"那是 $\\frac{1}{f(x)}$，不是反函數。"},{"label":"$3x + 1$","correct":true}]},{"ask":"$f$ 的定義域是 $[0, \\infty)$、值域是 $[2, \\infty)$。$f^{-1}$ 的定義域是？","options":[{"label":"$[2, \\infty)$","correct":true},{"label":"$[0, \\infty)$","why":"那是 $f^{-1}$ 的值域。$f^{-1}$ 吃進去的是 $f$ 吐出來的東西。"},{"label":"所有實數","why":"$f$ 只吐出 $\\ge 2$ 的值，$f^{-1}$ 也只能吃這些。"}]}],"practice":[]},"polynomial-rational":{"id":"polynomial-rational","prerequisites":["domain-range","function-arithmetic"],"next":["exp-log"],"related":["limit-factor","limit-at-infinity","infinite-limits"],"objectives":["會用因式定理：$p(a) = 0$ 若且唯若 $(x - a)$ 是 $p(x)$ 的因式，並用它把多項式分解。","看到有理函數，會找定義域，並分辨分母的零點是「洞」還是「垂直漸近線」。","知道 $x$ 很大時，多項式的行為由首項決定。"],"concept":[{"heading":"① 多項式","body":["$p(x) = a_nx^n + \\ldots + a_1x + a_0$（$a_n \\ne 0$），$n$ 叫次數，$a_nx^n$ 叫首項。多項式的定義域是全體實數，圖形是一條不斷開的光滑曲線。"]},{"heading":"② 因式定理：找到一個根，就拆出一個因式","body":["$p(a) = 0$ 若且唯若 $(x - a)$ 是 $p(x)$ 的因式。例：$p(x) = x^3 - 1$，$p(1) = 0$，所以 $x^3 - 1 = (x - 1)(x^2 + x + 1)$。","注意號：$p(2) = 0$ 給的是 $(x - 2)$，不是 $(x + 2)$。整係數多項式要猜根時，先試常數項的因數（$\\pm1$、$\\pm2$、$\\pm3$……）。","這是〈0/0：因式分解〉的核心：代 $x = a$ 讓分子分母都是 0，代表兩者都有 $(x - a)$ 這個因式，可以約掉。"]},{"heading":"③ 有理函數：多項式除以多項式","body":["$r(x) = \\frac{p(x)}{q(x)}$，定義域是 $q(x) \\ne 0$ 的地方。在 $q(a) = 0$ 的點，有兩種情況：","$p(a) \\ne 0$：分子不是 0、分母靠近 0，值會爆掉，圖形在 $x = a$ 有一條垂直漸近線（〈無窮極限與垂直漸近線〉）。","$p(a) = 0$：分子分母有共同因式 $(x - a)$，約掉後若分母不再是 0，圖形只是在 $x = a$ 少一個點，叫做洞。約掉後分母仍是 0、分子不是 0，那就還是漸近線。"]},{"heading":"④ $x$ 很大時看首項（直覺）","body":["$x = 1000$ 時 $2x^3 - 100x^2 = 2{,}000{,}000{,}000 - 100{,}000{,}000$，首項占了絕大部分。所以 $x$ 很大時，多項式的行為由首項決定，$\\frac{3x^2 + 1}{x^2 - 5}$ 會靠近 $\\frac{3x^2}{x^2} = 3$。","這只是直覺：「占了絕大部分」要怎麼說得精確，是〈x → ∞〉的內容。"]}],"workedExamples":[{"title":"猜一個根，拆成三個因式","prompt":"分解 $p(x) = x^3 - 2x^2 - 5x + 6$","steps":["試常數項 6 的因數。$p(1) = 1 - 2 - 5 + 6 = 0$，所以 $(x - 1)$ 是因式。","寫 $p(x) = (x - 1)(x^2 + bx + c)$。展開比較：常數項 $-c = 6$，$c = -6$；$x^2$ 項 $b - 1 = -2$，$b = -1$。檢查 $x$ 項：$c - b = -6 + 1 = -5$，對。","$x^2 - x - 6 = (x - 3)(x + 2)$。","$p(x) = (x - 1)(x - 3)(x + 2)$。"],"answer":"$(x - 1)(x - 3)(x + 2)$"},{"title":"洞還是漸近線","prompt":"$r(x) = \\frac{x^2 - 4}{x^2 - x - 2}$：找定義域，判斷每個被排除的點是洞還是垂直漸近線。","steps":["分解：分子 $(x - 2)(x + 2)$，分母 $(x - 2)(x + 1)$。分母為 0 在 $x = 2$、$x = -1$，定義域是 $x \\ne 2$、$x \\ne -1$。","$x = 2$：分子也是 0。約掉 $(x - 2)$，$x \\ne 2$ 時 $r(x) = \\frac{x + 2}{x + 1}$，這個式子在 2 的值是 $\\frac{4}{3}$，分母不是 0。$x = 2$ 是洞，洞在 $(2, \\frac{4}{3})$。","$x = -1$：分子 $(-1)^2 - 4 = -3 \\ne 0$，分母 0。$x = -1$ 是垂直漸近線。"],"answer":"定義域 $x \\ne 2$、$-1$；$x = 2$ 是洞，$x = -1$ 是垂直漸近線"},{"title":"首項決定遠方","prompt":"$x$ 很大時，$r(x) = \\frac{3x^2 + 1}{x^2 - 5}$ 大約是多少？","steps":["首項：分子 $3x^2$，分母 $x^2$，比值 3。","代 $x = 100$ 看看：$\\frac{30000 + 1}{10000 - 5} = \\frac{30001}{9995} \\approx 3.0016$。","$x$ 越大越靠近 3。"],"answer":"大約 3"}],"pitfalls":["因式定理號弄反：$p(2) = 0$ 寫成 $(x + 2)$。","看到分母為 0 就一律說是垂直漸近線，沒檢查分子。","約分之後忘了原本被排除的點。","只看首項就判斷 $x$ 在 0 附近的行為；首項只管 $x$ 很大的時候。"],"checks":[{"ask":"$p(x) = x^3 - 3x + 2$，$p(1) = 0$。下面哪一個一定是 $p(x)$ 的因式？","options":[{"label":"$x + 1$","why":"$p(1) = 0$ 對應的是 $x - 1$；$x + 1$ 對應的是 $p(-1) = 0$，但 $p(-1) = 4$。"},{"label":"$x - 1$","correct":true},{"label":"$x$","why":"$x$ 是因式要 $p(0) = 0$，但 $p(0) = 2$。"}]},{"ask":"$r(x) = \\frac{x - 3}{x^2 - 9}$。在 $x = 3$ 是？","options":[{"label":"洞","correct":true},{"label":"垂直漸近線","why":"分子在 3 也是 0；約掉 $x - 3$ 後是 $\\frac{1}{x + 3}$，在 3 的值是 $\\frac{1}{6}$，分母不是 0。"},{"label":"函數值是 $\\frac{1}{6}$","why":"$\\frac{1}{6}$ 是約分後的式子在 3 的值；原函數在 $x = 3$ 分母為 0，沒有定義。"}]},{"ask":"同一個 $r(x) = \\frac{x - 3}{x^2 - 9}$，在 $x = -3$ 是？","options":[{"label":"洞","why":"約分後 $\\frac{1}{x + 3}$ 在 $-3$ 分母仍是 0，分子是 1，不是洞。"},{"label":"函數值是 0","why":"分母是 0 的地方沒有函數值。"},{"label":"垂直漸近線","correct":true}]},{"ask":"$x$ 很大時，$\\frac{2x^3 - x}{x^3 + 5}$ 大約是？","options":[{"label":"2","correct":true},{"label":"0","why":"分子分母同樣是三次，不會縮到 0；只有分子次數比較低時才會。"},{"label":"越來越大","why":"分子分母同次，首項比值是 $\\frac{2x^3}{x^3} = 2$。"}]}],"practice":[{"id":"si-set-021","core":true,"note":"題目問「不連續點」；有理函數的不連續點就是分母的零點。"},{"id":"si-set-020","core":true},{"id":"si-set-003","core":true},{"id":"cx-curve-006","core":true},{"id":"cx-curve-004"}]},"exp-log":{"id":"exp-log","prerequisites":["inverse-function","domain-range"],"next":["trig-functions"],"related":["limit-e-type","derivative-exp"],"objectives":["會用指數律與對數律化簡，知道哪些「看起來很像」的式子其實是錯的。","知道 $\\ln$ 是 $e^x$ 的反函數：$\\ln(e^x) = x$，$e^{\\ln x} = x$（$x > 0$）。","會解簡單的指數、對數方程式，並且檢查定義域。"],"concept":[{"heading":"① 指數律","body":["底數 $a > 0$：$a^m \\cdot a^n = a^{m+n}$，$(a^m)^n = a^{mn}$，$a^0 = 1$，$a^{-n} = \\frac{1}{a^n}$，$a^{1/n} = \\sqrt[n]{a}$。","沒有「加法律」：$2^3 + 2^4$ 不是 $2^7$。"]},{"heading":"② 指數函數的長相","body":["$y = a^x$（$a > 0$、$a \\ne 1$）：永遠是正的，通過 $(0, 1)$。$a > 1$ 時遞增，往左貼近 0 但碰不到；$0 < a < 1$ 時遞減。","成長得非常快：$2^x$ 每往右走 1 就翻倍，$2^{10} = 1024$，$2^{20}$ 已經超過一百萬。反過來，對數長得非常慢：$\\ln 1000000 \\approx 13.8$。","微積分最常用的底數是 $e \\approx 2.71828$。為什麼是它：$e^x$ 在 $(0, 1)$ 的切線斜率剛好是 1，微分起來最乾淨（〈指數函數微分〉）；$e$ 本身怎麼來，〈e 型極限〉會講。"]},{"heading":"③ 對數：指數的反函數","body":["$\\log_a x = y$ 的意思是 $a^y = x$。它問的是「$a$ 的幾次方是 $x$」：$\\log_2 8 = 3$。$a^x$ 永遠是正的，所以 $\\log_a x$ 只吃 $x > 0$。","以 $e$ 為底的對數寫成 $\\ln x$。它們互為反函數：$\\ln(e^x) = x$ 對所有 $x$ 成立，$e^{\\ln x} = x$ 只在 $x > 0$ 成立。"],"tex":["\\ln(xy)=\\ln x+\\ln y,\\qquad \\ln\\frac{x}{y}=\\ln x-\\ln y,\\qquad \\ln(x^r)=r\\ln x\\qquad (x,y>0)"]},{"heading":"④ 對數律：把乘變加","body":["上面三條都來自指數律，而且都要求 $x$、$y > 0$。換底：$\\log_a x = \\ln x / \\ln a$，任何底的對數都能換成 $\\ln$。","$\\ln$ 沒有加法律：$\\ln(x + y)$ 沒有好的拆法，不等於 $\\ln x + \\ln y$。$(\\ln x)^2$ 也不是 $\\ln(x^2) = 2 \\ln x$。"]}],"workedExamples":[{"title":"化簡","prompt":"求 $\\log_2 8 + \\log_2\\left(\\frac{1}{2}\\right)$ 與 $e^{2 \\ln 3}$。","steps":["$\\log_2 8 = 3$（$2^3 = 8$），$\\log_2\\left(\\frac{1}{2}\\right) = -1$（$2^{-1} = \\frac{1}{2}$），和是 2。","$2 \\ln 3 = \\ln(3^2) = \\ln 9$。","$e^{\\ln 9} = 9$。"],"answer":"2；9"},{"title":"解指數方程式","prompt":"解 $2^{x+1} = 12$","steps":["兩邊取 $\\ln$：$(x + 1) \\ln 2 = \\ln 12$。","$x + 1 = \\ln 12 / \\ln 2 = \\log_2 12$。","$x = \\log_2 12 - 1 = \\log_2 12 - \\log_2 2 = \\log_2 6 \\approx 2.585$。","檢查：$2^{\\log_2 6 + 1} = 6 \\cdot 2 = 12$。"],"answer":"$x = \\log_2 6 = \\ln 6 / \\ln 2 \\approx 2.585$"},{"title":"換底","prompt":"把 $\\log_3 10$ 換成 $\\ln$ 表示，並估計它的值。","steps":["設 $y = \\log_3 10$，意思是 $3^y = 10$。","兩邊取 $\\ln$：$y \\ln 3 = \\ln 10$，所以 $y = \\ln 10 / \\ln 3$。","$\\ln 10 \\approx 2.3026$，$\\ln 3 \\approx 1.0986$，$y \\approx 2.096$。合理性：$3^2 = 9$ 比 10 小一點，所以 $y$ 比 2 大一點。"],"answer":"$\\log_3 10 = \\ln 10 / \\ln 3 \\approx 2.096$"},{"title":"解對數方程式，記得檢查","prompt":"解 $\\ln x + \\ln(x - 2) = \\ln 3$","steps":["先寫定義域：$x > 0$ 而且 $x - 2 > 0$，所以 $x > 2$。","合併：$\\ln(x(x - 2)) = \\ln 3$。$\\ln$ 是一對一的，所以 $x(x - 2) = 3$。","$x^2 - 2x - 3 = 0$，$(x - 3)(x + 1) = 0$，$x = 3$ 或 $x = -1$。","$x = -1$ 不滿足 $x > 2$，丟掉（$\\ln(-1)$ 根本沒有定義）。答案 $x = 3$。"],"answer":"$x = 3$"}],"pitfalls":["$\\ln(a + b)$ 拆成 $\\ln a + \\ln b$。","$e^{a+b}$ 寫成 $e^a + e^b$；正確是 $e^a \\cdot e^b$。","$(\\ln x)^2$ 與 $\\ln(x^2)$ 混為一談。","解完對數方程式沒有回頭檢查定義域。","以為 $e^{\\ln x} = x$ 對負的 $x$ 也成立。"],"checks":[{"ask":"$\\ln(e^5)$ 是？","options":[{"label":"$e^5$","why":"$\\ln$ 跟 $e$ 的次方互相抵消，剩下指數 5。"},{"label":"$5e$","why":"$\\ln$ 不是乘法；它問的是「$e$ 的幾次方」，$e^5$ 是 $e$ 的 5 次方。"},{"label":"5","correct":true}]},{"ask":"$\\ln 6$ 等於？","options":[{"label":"$\\ln 2 + \\ln 3$","correct":true},{"label":"$\\ln 2 \\cdot \\ln 3$","why":"乘積的 $\\ln$ 是 $\\ln$ 的和，不是 $\\ln$ 的積。"},{"label":"$\\ln 4 + \\ln 2$","why":"$4 + 2 = 6$，但 $\\ln$ 把「乘」變成「加」：$\\ln 4 + \\ln 2 = \\ln 8$。"}]},{"ask":"$e^{2 \\ln 3}$ 是？","options":[{"label":"6","why":"$2 \\ln 3 = \\ln(3^2) = \\ln 9$，不是 $\\ln 6$。"},{"label":"9","correct":true},{"label":"$e^6$","why":"$e$ 與 $\\ln$ 抵消之後只剩 $3^2$，不會留下 $e$。"}]},{"ask":"$\\ln(x - 2)$ 的定義域？","options":[{"label":"$x \\ge 2$","why":"$x = 2$ 時是 $\\ln 0$，沒有定義；$e$ 的任何次方都不是 0。"},{"label":"所有實數","why":"對數只吃正數，$x - 2$ 要大於 0。"},{"label":"$x > 2$","correct":true}]}],"practice":[{"id":"si-int-001","core":true},{"id":"si-int-011","core":true},{"id":"si-int-014","challenge":true,"note":"挑戰：$\\ln(\\ln x)$ 要兩層都成立：$x > 0$，而且 $\\ln x > 0$。"}]},"trig-functions":{"id":"trig-functions","prerequisites":["function-intro","graph-features"],"next":["trig-identities"],"related":["limit-trig-standard"],"objectives":["會在角度與弧度之間換算，知道微積分一律用弧度。","用單位圓讀出特殊角的 $\\sin$、$\\cos$、$\\tan$，包含正負號。","說得出 $\\sin$、$\\cos$、$\\tan$ 的週期與定義域，會算 $\\sin(bx)$ 的週期。"],"concept":[{"heading":"① 弧度：用弧長量角度","body":["在半徑 1 的圓上，角 $\\theta$ 對到的弧長就是 $\\theta$ 的弧度數。繞一整圈弧長 $2\\pi$，所以 $360^\\circ = 2\\pi$，$180^\\circ = \\pi$，1 弧度約 $57.3^\\circ$。","微積分一律用弧度。像 $(\\sin x)' = \\cos x$、〈三角標準極限〉的 $\\sin x / x \\to 1$，只有在弧度下才成立；用角度會多出 $\\frac{\\pi}{180}$ 這種係數。"]},{"heading":"② 單位圓定義","body":["從正 $x$ 軸逆時針轉 $\\theta$（順時針是負角），終邊跟單位圓的交點就是 $(\\cos \\theta, \\sin \\theta)$。所以 $\\cos \\theta$ 是橫座標、$\\sin \\theta$ 是縱座標，兩者都在 $-1$ 到 1 之間，而且 $\\sin^2\\theta + \\cos^2\\theta = 1$（〈三角恆等式〉）。","$\\tan \\theta = \\sin \\theta / \\cos \\theta$，在 $\\cos \\theta = 0$ 的地方沒有定義：$\\theta = \\frac{\\pi}{2} + k\\pi$（$k$ 是整數）。"]},{"heading":"③ 特殊角與正負號","body":["第一象限要記的：$\\sin\\left(\\frac{\\pi}{6}\\right) = \\frac{1}{2}$，$\\sin\\left(\\frac{\\pi}{4}\\right) = \\frac{\\sqrt{2}}{2}$，$\\sin\\left(\\frac{\\pi}{3}\\right) = \\frac{\\sqrt{3}}{2}$；$\\cos$ 的值順序相反。","其他象限：先找參考角（終邊跟 $x$ 軸的夾角），值的大小跟參考角一樣，正負看點在哪個象限：第二象限 $x$ 負、$y$ 正，第三象限都負，第四象限 $x$ 正、$y$ 負。"],"tex":["\\begin{array}{c|ccccc} \\theta & 0 & \\pi/6 & \\pi/4 & \\pi/3 & \\pi/2 \\\\ \\hline \\sin\\theta & 0 & 1/2 & \\sqrt2/2 & \\sqrt3/2 & 1 \\\\ \\cos\\theta & 1 & \\sqrt3/2 & \\sqrt2/2 & 1/2 & 0 \\end{array}"]},{"heading":"④ 週期與對稱","body":["繞一圈回到原點，所以 $\\sin$、$\\cos$ 的週期是 $2\\pi$；$\\tan$ 的週期是 $\\pi$。","$\\sin(bx)$ 的週期是 $2\\pi/|b|$：括號裡乘 $b$，波形擠 $b$ 倍。$\\sin$ 是奇函數，$\\cos$ 是偶函數：$\\sin(-\\theta) = -\\sin \\theta$，$\\cos(-\\theta) = \\cos \\theta$。"]}],"workedExamples":[{"title":"第二象限的角","prompt":"把 $150^\\circ$ 換成弧度，並求 $\\sin$ 與 $\\cos$。","steps":["$150^\\circ \\times \\frac{\\pi}{180^\\circ} = \\frac{5\\pi}{6}$。","$\\frac{5\\pi}{6}$ 在第二象限，參考角 $\\pi - \\frac{5\\pi}{6} = \\frac{\\pi}{6}$。","大小：$\\sin\\left(\\frac{\\pi}{6}\\right) = \\frac{1}{2}$，$\\cos\\left(\\frac{\\pi}{6}\\right) = \\frac{\\sqrt{3}}{2}$。","第二象限 $y$ 正、$x$ 負：$\\sin\\left(\\frac{5\\pi}{6}\\right) = \\frac{1}{2}$，$\\cos\\left(\\frac{5\\pi}{6}\\right) = -\\frac{\\sqrt{3}}{2}$。"],"answer":"$\\frac{5\\pi}{6}$；$\\sin = \\frac{1}{2}$，$\\cos = -\\frac{\\sqrt{3}}{2}$"},{"title":"第三象限的 $\\tan$","prompt":"求 $\\tan\\left(\\frac{4\\pi}{3}\\right)$","steps":["$\\frac{4\\pi}{3} = \\pi + \\frac{\\pi}{3}$，在第三象限，參考角 $\\frac{\\pi}{3}$。","$\\sin\\left(\\frac{4\\pi}{3}\\right) = -\\frac{\\sqrt{3}}{2}$，$\\cos\\left(\\frac{4\\pi}{3}\\right) = -\\frac{1}{2}$（第三象限兩個都負）。","$\\tan = \\frac{\\sin}{\\cos} = \\left(-\\frac{\\sqrt{3}}{2}\\right)/\\left(-\\frac{1}{2}\\right) = \\sqrt{3}$。"],"answer":"$\\sqrt{3}$"},{"title":"週期與值域","prompt":"$f(x) = 3 \\sin(2x)$ 的週期與值域","steps":["週期：$\\frac{2\\pi}{2} = \\pi$。檢查：$f(x + \\pi) = 3 \\sin(2x + 2\\pi) = 3 \\sin(2x)$。","週期不是 $\\frac{\\pi}{2}$：$f\\left(\\frac{\\pi}{4}\\right) = 3 \\sin\\left(\\frac{\\pi}{2}\\right) = 3$，$f(\\frac{\\pi}{4} + \\frac{\\pi}{2}) = f\\left(\\frac{3\\pi}{4}\\right) = 3 \\sin\\left(\\frac{3\\pi}{2}\\right) = -3$，不一樣。","$\\sin$ 的值在 $[-1, 1]$，乘 3 之後在 $[-3, 3]$，而且 $\\pm3$ 都取得到。"],"answer":"週期 $\\pi$，值域 $[-3, 3]$"}],"pitfalls":["計算機停在角度模式，或把度數直接代進微積分公式。","象限的正負號弄錯，例如把 $\\cos\\left(\\frac{5\\pi}{6}\\right)$ 寫成正的。","$\\sin(2x)$ 的週期寫成 $4\\pi$：括號裡乘 2，週期要除以 2。","$\\sin^2x$ 讀成 $\\sin(x^2)$；$\\sin^2x$ 的意思是 $(\\sin x)^2$。"],"checks":[{"ask":"$\\cos\\left(\\frac{\\pi}{3}\\right)$ 是？","options":[{"label":"$\\frac{\\sqrt{3}}{2}$","why":"那是 $\\sin\\left(\\frac{\\pi}{3}\\right)$。$\\frac{\\pi}{3}$ 的終邊比較靠近 $y$ 軸，橫座標比較小。"},{"label":"$\\frac{1}{2}$","correct":true},{"label":"$-\\frac{1}{2}$","why":"$\\frac{\\pi}{3}$ 在第一象限，$\\cos$ 是正的。"}]},{"ask":"$\\sin\\left(\\frac{7\\pi}{6}\\right)$ 是？","options":[{"label":"$-\\frac{1}{2}$","correct":true},{"label":"$\\frac{1}{2}$","why":"$\\frac{7\\pi}{6}$ 在第三象限，縱座標是負的。"},{"label":"$-\\frac{\\sqrt{3}}{2}$","why":"參考角是 $\\frac{7\\pi}{6} - \\pi = \\frac{\\pi}{6}$，$\\sin\\left(\\frac{\\pi}{6}\\right) = \\frac{1}{2}$，不是 $\\frac{\\sqrt{3}}{2}$。"}]},{"ask":"$\\cos(3x)$ 的週期是？","options":[{"label":"$6\\pi$","why":"括號裡乘 3 讓波形變密，週期要除以 3，不是乘 3。"},{"label":"$2\\pi$","why":"那是 $\\cos x$ 的週期。"},{"label":"$\\frac{2\\pi}{3}$","correct":true}]},{"ask":"$\\tan x$ 在哪些地方沒有定義？","options":[{"label":"$x = k\\pi$（$k$ 是整數）","why":"那是 $\\sin x = 0$ 的地方，$\\tan$ 在那裡等於 0，有定義。"},{"label":"$x = \\frac{\\pi}{2} + k\\pi$（$k$ 是整數）","correct":true},{"label":"$x = \\frac{\\pi}{4}$","why":"$\\tan\\left(\\frac{\\pi}{4}\\right) = 1$，有定義。"}]}],"practice":[{"id":"si-set-022","core":true,"note":"題目問「不連續點」；$\\tan$ 的不連續點就是它沒有定義的地方。"},{"id":"gr-009","core":true},{"id":"gi-005","note":"在單位圓上，縱座標什麼時候最大、最小？"},{"id":"sk-035"}]},"trig-identities":{"id":"trig-identities","prerequisites":["trig-functions"],"next":["inverse-trig"],"related":["limit-trig-standard","trig-identity-integrals"],"objectives":["從單位圓說出 $\\sin^2x + \\cos^2x = 1$，並由它推出 $1 + \\tan^2x = \\sec^2x$。","會用倍角公式，並能把 $\\cos 2x$ 寫成三種形式。","會用半角（降次）公式把 $\\sin^2x$、$\\cos^2x$ 換成一次的 $\\cos 2x$。"],"concept":[{"heading":"① 最基本的一條","body":["單位圓上的點 $(\\cos x, \\sin x)$ 到原點距離 1，畢氏定理給出 $\\sin^2x + \\cos^2x = 1$。$\\sin^2x$ 的意思是 $(\\sin x)^2$。","兩邊除以 $\\cos^2x$（$\\cos x \\ne 0$）：$\\tan^2x + 1 = \\sec^2x$，其中 $\\sec x = \\frac{1}{\\cos x}$。同樣，$\\csc x = \\frac{1}{\\sin x}$，$\\cot x = \\frac{\\cos x}{\\sin x}$。","知道 $\\sin x$ 就知道 $|\\cos x|$，正負號要看 $x$ 在哪個象限。"],"tex":["\\sin^2x+\\cos^2x=1,\\qquad 1+\\tan^2x=\\sec^2x"]},{"heading":"② 和角公式（工具，先接受）","body":["$\\sin(a + b) = \\sin a \\cos b + \\cos a \\sin b$，$\\cos(a + b) = \\cos a \\cos b - \\sin a \\sin b$。","它們不是 $\\sin a + \\sin b$：$\\sin(\\frac{\\pi}{2} + \\frac{\\pi}{2}) = \\sin \\pi = 0$，但 $\\sin\\left(\\frac{\\pi}{2}\\right) + \\sin\\left(\\frac{\\pi}{2}\\right) = 2$。"]},{"heading":"③ 倍角：令 $a = b = x$","body":["$\\sin 2x = 2 \\sin x \\cos x$；$\\cos 2x = \\cos^2x - \\sin^2x$。","用 $\\sin^2x + \\cos^2x = 1$ 把 $\\cos 2x$ 改寫成只有一種函數：$\\cos 2x = 2\\cos^2x - 1 = 1 - 2\\sin^2x$。三種形式都對，看題目要什麼選哪一種。"]},{"heading":"④ 半角（降次）：把平方變成一次","body":["把 $\\cos 2x = 2\\cos^2x - 1$ 與 $\\cos 2x = 1 - 2\\sin^2x$ 各自解出平方項，就得到下面兩條。左邊是平方，右邊只有一次的 $\\cos 2x$。","這兩條之後很常用：〈三角標準極限〉用 $1 - \\cos x = 2 \\sin^2\\left(\\frac{x}{2}\\right)$；〈用三角恆等式積分〉用它們積 $\\sin^2x$、$\\cos^2x$。"],"tex":["\\cos^2x=\\frac{1+\\cos 2x}{2},\\qquad \\sin^2x=\\frac{1-\\cos 2x}{2}"]}],"workedExamples":[{"title":"由 $\\sin$ 求其他值","prompt":"$\\sin x = \\frac{3}{5}$，$x$ 在第二象限。求 $\\cos x$、$\\tan x$、$\\sin 2x$、$\\cos 2x$。","steps":["$\\cos^2x = 1 - \\frac{9}{25} = \\frac{16}{25}$，$|\\cos x| = \\frac{4}{5}$。第二象限 $\\cos$ 為負：$\\cos x = -\\frac{4}{5}$。","$\\tan x = \\left(\\frac{3}{5}\\right)/\\left(-\\frac{4}{5}\\right) = -\\frac{3}{4}$。","$\\sin 2x = 2 \\sin x \\cos x = 2 \\cdot \\left(\\frac{3}{5}\\right) \\cdot \\left(-\\frac{4}{5}\\right) = -\\frac{24}{25}$。","$\\cos 2x = 1 - 2\\sin^2x = 1 - \\frac{18}{25} = \\frac{7}{25}$。"],"answer":"$\\cos x = -\\frac{4}{5}$，$\\tan x = -\\frac{3}{4}$，$\\sin 2x = -\\frac{24}{25}$，$\\cos 2x = \\frac{7}{25}$"},{"title":"半角求值","prompt":"求 $\\cos\\left(\\frac{\\pi}{8}\\right)$","steps":["$\\frac{\\pi}{8}$ 是 $\\frac{\\pi}{4}$ 的一半。用 $\\cos^2x = \\frac{1 + \\cos 2x}{2}$，$x = \\frac{\\pi}{8}$：$\\cos^2\\left(\\frac{\\pi}{8}\\right) = (1 + \\cos\\left(\\frac{\\pi}{4}\\right))/2 = (1 + \\frac{\\sqrt{2}}{2})/2 = \\frac{2 + \\sqrt{2}}{4}$。","開根號：$|\\cos\\left(\\frac{\\pi}{8}\\right)| = \\frac{\\sqrt{2 + \\sqrt{2}}}{2}$。","$\\frac{\\pi}{8}$ 在第一象限，$\\cos$ 為正：$\\cos\\left(\\frac{\\pi}{8}\\right) = \\frac{\\sqrt{2 + \\sqrt{2}}}{2} \\approx 0.924$。"],"answer":"$\\frac{\\sqrt{2 + \\sqrt{2}}}{2}$"},{"title":"化簡","prompt":"化簡 $\\frac{1 - \\cos 2x}{\\sin 2x}$","steps":["分子：$1 - \\cos 2x = 2 \\sin^2x$（由 $\\cos 2x = 1 - 2\\sin^2x$）。","分母：$\\sin 2x = 2 \\sin x \\cos x$。","相除：$2 \\sin^2x / (2 \\sin x \\cos x) = \\sin x / \\cos x = \\tan x$（在 $\\sin 2x \\ne 0$ 的地方）。"],"answer":"$\\tan x$"}],"pitfalls":["$\\sin 2x$ 寫成 $2 \\sin x$。","$\\sin(a + b)$ 寫成 $\\sin a + \\sin b$。","$\\cos^2x$ 跟 $\\cos(x^2)$ 搞混。","由 $\\sin^2x + \\cos^2x = 1$ 開根號時，沒依象限決定正負號。","降次公式把 $\\cos 2x$ 寫成 $\\cos x$。"],"checks":[{"ask":"$\\cos 2x$ 等於下面哪一個？","options":[{"label":"$2 \\cos x$","why":"倍角不是把 2 提出來：$x = 0$ 時 $\\cos 0 = 1$，但 $2 \\cos 0 = 2$。"},{"label":"$1 - 2\\sin^2x$","correct":true},{"label":"$\\cos^2x + \\sin^2x$","why":"那恆等於 1；$\\cos 2x$ 是 $\\cos^2x$ 減 $\\sin^2x$。"}]},{"ask":"$\\sin^2x$ 降次後是？","options":[{"label":"$\\frac{1 - \\cos 2x}{2}$","correct":true},{"label":"$\\frac{1 + \\cos 2x}{2}$","why":"那是 $\\cos^2x$。用 $x = 0$ 檢查：$\\sin^{2}0 = 0$，但 $\\frac{1 + \\cos 0}{2} = 1$。"},{"label":"$\\frac{1 - \\cos x}{2}$","why":"降次時角度要加倍。$x = \\pi$ 時 $\\sin^2\\pi = 0$，但 $\\frac{1 - \\cos \\pi}{2} = 1$。"}]},{"ask":"$\\cos x = -\\frac{1}{3}$，而且 $\\pi < x < \\frac{3\\pi}{2}$。$\\sin x$ 是？","options":[{"label":"$\\frac{2\\sqrt{2}}{3}$","why":"$\\pi < x < \\frac{3\\pi}{2}$ 是第三象限，$\\sin$ 為負。"},{"label":"$-\\frac{2}{3}$","why":"$\\sin^2x = 1 - \\frac{1}{9} = \\frac{8}{9}$，開根號是 $\\frac{\\sqrt{8}}{3} = \\frac{2\\sqrt{2}}{3}$，不是 $\\frac{2}{3}$。"},{"label":"$-\\frac{2\\sqrt{2}}{3}$","correct":true}]},{"ask":"$1 + \\tan^2x$ 等於？","options":[{"label":"1","why":"等於 1 的是 $\\sin^2x + \\cos^2x$；把它除以 $\\cos^2x$ 才得到 $1 + \\tan^2x$。"},{"label":"$\\sec^2x$","correct":true},{"label":"$\\csc^2x$","why":"那是 $1 + \\cot^2x$（把 $\\sin^2x + \\cos^2x = 1$ 除以 $\\sin^2x$）。"}]}],"practice":[]},"inverse-trig":{"id":"inverse-trig","prerequisites":["inverse-function","trig-functions","trig-identities"],"next":["limit-intro"],"related":["inverse-trig-derivative","limit-at-infinity"],"objectives":["說得出 $\\arcsin$、$\\arccos$、$\\arctan$ 各自的定義域與值域，以及為什麼要限制。","會求特殊值，答案一定落在值域裡。","分清楚 $\\sin(\\arcsin x) = x$ 永遠成立，而 $\\arcsin(\\sin x) = x$ 只在 $x \\in [-\\frac{\\pi}{2}, \\frac{\\pi}{2}]$ 成立。"],"concept":[{"heading":"① 先把 $\\sin$ 剪成一對一","body":["$\\sin$ 不是一對一：$\\sin\\left(\\frac{\\pi}{6}\\right) = \\sin\\left(\\frac{5\\pi}{6}\\right) = \\frac{1}{2}$。所以「哪個角的 $\\sin$ 是 $\\frac{1}{2}$」有無限多個答案，沒有反函數。","只留 $[-\\frac{\\pi}{2}, \\frac{\\pi}{2}]$ 這段：$\\sin$ 在這段從 $-1$ 一路增加到 1，每個值剛好一次。這段的反函數叫 $\\arcsin$，也寫成 $\\sin^{-1}$。"]},{"heading":"② 三個反三角函數","body":["$\\arcsin x$：定義域 $[-1, 1]$，值域 $[-\\frac{\\pi}{2}, \\frac{\\pi}{2}]$。意思是「$[-\\frac{\\pi}{2}, \\frac{\\pi}{2}]$ 裡，$\\sin$ 等於 $x$ 的那個角」。","$\\arccos x$：$\\cos$ 剪在 $[0, \\pi]$。定義域 $[-1, 1]$，值域 $[0, \\pi]$。","$\\arctan x$：$\\tan$ 剪在 $(-\\frac{\\pi}{2}, \\frac{\\pi}{2})$。定義域是全體實數，值域 $(-\\frac{\\pi}{2}, \\frac{\\pi}{2})$。$x \\to \\infty$ 時 $\\arctan x$ 往 $\\frac{\\pi}{2}$ 靠，圖形有兩條水平漸近線 $y = \\pm\\frac{\\pi}{2}$（〈x → ∞〉）。"],"tex":["\\arcsin:[-1,1]\\to\\left[-\\tfrac{\\pi}{2},\\tfrac{\\pi}{2}\\right],\\quad \\arccos:[-1,1]\\to[0,\\pi],\\quad \\arctan:\\mathbb{R}\\to\\left(-\\tfrac{\\pi}{2},\\tfrac{\\pi}{2}\\right)"]},{"heading":"③ 兩個方向的抵消不一樣","body":["$\\sin(\\arcsin x) = x$ 對 $[-1, 1]$ 裡每個 $x$ 都成立：先找角、再取 $\\sin$，回到原數。","$\\arcsin(\\sin x) = x$ 只在 $x \\in [-\\frac{\\pi}{2}, \\frac{\\pi}{2}]$ 成立。$\\arcsin$ 永遠回傳 $[-\\frac{\\pi}{2}, \\frac{\\pi}{2}]$ 裡的角，所以 $\\arcsin(\\sin\\left(\\frac{5\\pi}{6}\\right)) = \\arcsin\\left(\\frac{1}{2}\\right) = \\frac{\\pi}{6}$，不是 $\\frac{5\\pi}{6}$。"]},{"heading":"④ 記號","body":["$\\sin^{-1} x$ 是 $\\arcsin x$，不是 $\\frac{1}{\\sin x}$（那是 $\\csc x$）。但 $\\sin^2x$ 又是 $(\\sin x)^2$。上標 $-1$ 是反函數的記號，跟次方無關，這是歷史留下的不一致，看到要分清楚。","這三個函數的導數在〈反函數與反三角函數微分〉；它們的導數是很乾淨的代數式，這是之後積分裡常看到 $\\arctan$ 的原因。"]}],"workedExamples":[{"title":"特殊值：答案要落在值域","prompt":"求 $\\arcsin\\left(-\\frac{1}{2}\\right)$、$\\arccos\\left(-\\frac{1}{2}\\right)$、$\\arctan(\\sqrt{3})$。","steps":["$\\arcsin\\left(-\\frac{1}{2}\\right)$：$[-\\frac{\\pi}{2}, \\frac{\\pi}{2}]$ 裡 $\\sin$ 是 $-\\frac{1}{2}$ 的角是 $-\\frac{\\pi}{6}$。$\\frac{7\\pi}{6}$ 的 $\\sin$ 也是 $-\\frac{1}{2}$，但不在值域裡。","$\\arccos\\left(-\\frac{1}{2}\\right)$：$[0, \\pi]$ 裡 $\\cos$ 是 $-\\frac{1}{2}$ 的角。參考角 $\\frac{\\pi}{3}$，$\\cos$ 為負在第二象限：$\\pi - \\frac{\\pi}{3} = \\frac{2\\pi}{3}$。","$\\arctan(\\sqrt{3})$：$(-\\frac{\\pi}{2}, \\frac{\\pi}{2})$ 裡 $\\tan$ 是 $\\sqrt{3}$ 的角是 $\\frac{\\pi}{3}$。"],"answer":"$-\\frac{\\pi}{6}$；$\\frac{2\\pi}{3}$；$\\frac{\\pi}{3}$"},{"title":"先 $\\sin$ 再 $\\arcsin$","prompt":"求 $\\arcsin(\\sin\\left(\\frac{5\\pi}{6}\\right))$","steps":["$\\frac{5\\pi}{6}$ 不在 $[-\\frac{\\pi}{2}, \\frac{\\pi}{2}]$，不能直接抵消。","先算裡面：$\\sin\\left(\\frac{5\\pi}{6}\\right) = \\frac{1}{2}$。","再算 $\\arcsin\\left(\\frac{1}{2}\\right)$：$[-\\frac{\\pi}{2}, \\frac{\\pi}{2}]$ 裡 $\\sin$ 是 $\\frac{1}{2}$ 的角是 $\\frac{\\pi}{6}$。"],"answer":"$\\frac{\\pi}{6}$"},{"title":"三角函數套反三角函數","prompt":"把 $\\cos(\\arcsin x)$ 寫成 $x$ 的代數式（$-1 \\le x \\le 1$）","steps":["令 $\\theta = \\arcsin x$，所以 $\\sin \\theta = x$，而且 $\\theta \\in [-\\frac{\\pi}{2}, \\frac{\\pi}{2}]$。","$\\cos^2\\theta = 1 - \\sin^2\\theta = 1 - x^2$，所以 $|\\cos \\theta| = \\sqrt{1 - x^2}$。","$\\theta \\in [-\\frac{\\pi}{2}, \\frac{\\pi}{2}]$ 時 $\\cos \\theta \\ge 0$，取正號：$\\cos(\\arcsin x) = \\sqrt{1 - x^2}$。","畫圖也行：斜邊 1、對邊 $x$ 的直角三角形，鄰邊 $\\sqrt{1 - x^2}$。"],"answer":"$\\sqrt{1 - x^2}$"}],"pitfalls":["$\\arcsin\\left(-\\frac{1}{2}\\right)$ 寫成 $\\frac{7\\pi}{6}$ 或 $\\frac{11\\pi}{6}$：答案必須在 $[-\\frac{\\pi}{2}, \\frac{\\pi}{2}]$。","以為 $\\arcsin(\\sin x) = x$ 永遠成立。","把 $\\sin^{-1} x$ 當成 $\\frac{1}{\\sin x}$。","以為 $\\arccos(-x) = -\\arccos x$；$\\arccos$ 的值永遠在 $[0, \\pi]$，不會是負的。","寫出 $\\arcsin 2$：$\\sin$ 的值不會超過 1，$\\arcsin 2$ 沒有定義。"],"checks":[{"ask":"$\\arccos(0)$ 是？","options":[{"label":"0","why":"$\\cos 0 = 1$，不是 0。"},{"label":"$\\frac{\\pi}{2}$","correct":true},{"label":"$-\\frac{\\pi}{2}$","why":"$\\cos\\left(-\\frac{\\pi}{2}\\right)$ 也是 0，但 $\\arccos$ 的值在 $[0, \\pi]$。"}]},{"ask":"$\\arctan(-1)$ 是？","options":[{"label":"$\\frac{3\\pi}{4}$","why":"$\\tan\\left(\\frac{3\\pi}{4}\\right) = -1$ 沒錯，但 $\\arctan$ 只回傳 $(-\\frac{\\pi}{2}, \\frac{\\pi}{2})$ 裡的那一個。"},{"label":"$-\\frac{\\pi}{4}$","correct":true},{"label":"$\\frac{\\pi}{4}$","why":"$\\tan\\left(\\frac{\\pi}{4}\\right) = 1$，不是 $-1$。"}]},{"ask":"$\\arcsin(\\sin\\left(\\frac{3\\pi}{4}\\right))$ 是？","options":[{"label":"$\\frac{\\pi}{4}$","correct":true},{"label":"$\\frac{3\\pi}{4}$","why":"$\\frac{3\\pi}{4}$ 不在 $[-\\frac{\\pi}{2}, \\frac{\\pi}{2}]$；$\\arcsin$ 回傳的是那個範圍裡 $\\sin$ 值相同的角。"},{"label":"$-\\frac{\\pi}{4}$","why":"$\\sin\\left(\\frac{3\\pi}{4}\\right) = \\frac{\\sqrt{2}}{2}$ 是正的，$\\arcsin$ 的結果也是正的。"}]},{"ask":"$\\sin^{-1}\\left(\\frac{1}{2}\\right)$ 的意思是？","options":[{"label":"$\\frac{1}{\\sin\\left(\\frac{1}{2}\\right)}$","why":"那是 $\\csc\\left(\\frac{1}{2}\\right)$。$\\sin^{-1}$ 的 $-1$ 表示反函數。"},{"label":"2","why":"$\\left(\\frac{1}{2}\\right)^{-1} = 2$ 是把 $-1$ 次方用在數字上；$\\sin^{-1}$ 是作用在 $\\sin$ 這個函數上。"},{"label":"$\\arcsin\\left(\\frac{1}{2}\\right) = \\frac{\\pi}{6}$","correct":true}]}],"practice":[]}});
